private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    int required = length + size;
    if (required <= data.length) {
        return;
    }
    int newCap = data.length > 0 ? Math.max(data.length * 2, required) : required;
    try {
        byte[] newData = new byte[newCap];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    } catch (OutOfMemoryError e) {
        throw new RuntimeException("Unable to enlarge byte vector", e);
    }
}

