private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> left = node.left;
    if (left == null) {
        // Cannot rotate if there is no left child; return node unchanged.
        return node;
    }
    // Perform rotation: detach left's right subtree as node's left child.
    node.left = left.right;
    // Attach node as right child of left.
    left.right = node;
    // If TreeNode contains a parent pointer, update it if present.
    // (If the parent field does not exist, accessing it will be a compilation error and should be removed.)
    try {
        java.lang.reflect.Field parentField = TreeNode.class.getDeclaredField("parent");
        parentField.setAccessible(true);
        Object parent = parentField.get(node);
        parentField.set(left, parent);
        parentField.set(node, left);
    } catch (NoSuchFieldException | IllegalAccessException ignored) {
        // No parent field; ignore.
    }
    return left;
}

