        @SuppressWarnings("unchecked")
        V vertex = (V) (Object) key; // casting string to V; assumes V is String or compatible
        target.addVertex(vertex);
        resultMap.put(key, vertex);
    }

    // Add vertices for side B
    for (int j = 0; j < sideSizeB; j++) {
        String key = "V" + j;
        @SuppressWarnings("unchecked")
        V vertex = (V) (Object) key;
        target.addVertex(vertex);
        resultMap.put(key, vertex);
    }

    // Add all edges between vertices of the two sides
    for (Map.Entry<String, V> entryA : resultMap.entrySet()) {
        if (!entryA.getKey().startsWith("U")) continue;
        V u = entryA.getValue();
        for (Map.Entry<String, V> entryB : resultMap.entrySet()) {
