public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType param = (ParameterizedType) genericType;
    Type[] args = param.getActualTypeArguments();
    Class<?>[] res = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Class<?> r = resolveRawClass(args[i], targetType);
        if (r == null) {
            return null;
        }
        res[i] = r;
    }
    return res;
}

private static Class<?> resolveRawClass(Type t, Class<?> targetType) {
    if (t instanceof Class<?>) {
        return (Class<?>) t;
    }
    if (t instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) t).getRawType();
    }
    if (t instanceof GenericArrayType) {
        Type component = ((GenericArrayType) t).getGenericComponentType();
        Class<?> componentCls = resolveRawClass(component, targetType);
        if (componentCls == null) {
            return null;
        }
        return java.lang.reflect.Array.newInstance(componentCls, 0).getClass();
    }
    if (t instanceof WildcardType) {
        Type[] upper = ((WildcardType) t).getUpperBounds();
        if (upper.length > 0) {
            return resolveRawClass(upper[0], targetType);
        }
    }
    // TypeVariable or other types cannot be resolved to a raw class
    return null;
}

