public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mapping for the specified table
    Mappings currentMapping = m_tableMap.get(tableName.toLowerCase());
    if (currentMapping == null) {
        // No current mapping found – return an empty Mappings object
        return new Mappings();
    }

    try {
        // Assume Mappings exposes a method that returns the underlying
        // properties map and a way to set a new properties map.
        Map<String, Object> currentProps = currentMapping.getProperties();
        Map<String, Object> historyProps = mappings.getProperties();

        // Compute the fields present in the current mapping but absent
        // in the historical (input) mapping, excluding the "_source" field.
        Map<String, Object> diffProps = new LinkedHashMap<>();
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String field = entry.getKey();
            if ("_source".equals(field) || historyProps.containsKey(field)) {
                continue;
            }
            diffProps.put(field, entry.getValue());
        }

        // Build the result mapping consisting solely of the missing fields
        Mappings diff = new Mappings();
        diff.setProperties(diffProps);
        return diff;
    } catch (Exception e) {
        // On any error, return an empty mapping to avoid a crash
        return new Mappings();
    }
}

