static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day   = timeBucket % 100;
    if (month < 1 || month > 12 || day < 1) {
        throw new IllegalArgumentException("invalid timeBucket value");
    }
    long newDay = day - ((day - 1) % dayStep);
    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
        return 0;
    }
    int strLen = str.length();
    // Normalize index and length
    int start = index;
    int length = len;
    if (start < 0) {
        start = 0;
    }
    if (length < 0) {
        return 0;
    }
    int end = start + length;
    if (end > strLen) {
        end = strLen;
    }
    if (start >= end) {
        return 0;
    }
    int size = 0;
    int i = start;
    while (i < end) {
        int codePoint = str.codePointAt(i);
        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += Character.charCount(codePoint);
    }
    return size;
}

