public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    try {
        byte[] bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
        // Append the encoded bytes to the buffer
        if (lb != null) {
            lb.write(bytes, 0, bytes.length);
        }
        // Update the write session with the number of bytes written, if a session is provided
        if (session != null) {
            session.update(bytes.length);
        }
    } catch (Exception e) {
        throw new RuntimeException("Unable to write UTF-8 bytes", e);
    }
    return lb;
}

public void removeFromTreeEdgeList(){
