@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    // Allow null inputs to be converted to null
    if (value == null) {
        return null;
    }
    // This converter only handles java.lang.Character
    if (!Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException("Target type must be Character but was: " + type);
    }
    // If already a Character, return as is
    if (value instanceof Character) {
        return value;
    }
    // Handle string values – take the first character if the string is non-empty
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() > 0) {
            return cs.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert an empty string to Character");
        }
    }
    // Handle numeric values – convert via intValue() to char
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= 0 && intVal <= 65535) {
            return (char) intVal;
        }
        throw new IllegalArgumentException("Numeric value out of char range: " + value);
    }
    // Handle char[] with exactly one element
    if (value.getClass().isArray() && value.getClass().getComponentType() == char.class) {
        char[] arr = (char[]) value;
        if (arr.length == 1) {
            return arr[0];
        } else {
            throw new IllegalArgumentException("Array length > 1 cannot be converted to a single Character");
        }
    }
    // If none of the above apply, conversion fails
    throw new IllegalArgumentException("Cannot convert type " + value.getClass() + " to Character: " + value);
}

