    System.arraycopy(array, 0, newArray, 0, oldLen);
    return newArray;
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }
    int minSize = Math.min(set1.size(), set2.size());
    Set<V> result = new HashSet<>(minSize);
    if (set1.size() <= set2.size()) {
        for (V elem : set1) {
            if (set2.contains(elem)) {
                result.add(elem);
            }
        }
    } else {
        for (V elem : set2) {
            if (set1.contains(elem)) {
                result.add(elem);
            }
        }
    }
    return result;
}

