private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObject json = new JsonObject();
    if (properties == null) {
        return json;
    }
    for (KeyStringValuePair kv : properties) {
        if (kv == null) {
            continue;
        }
        String key = null;
        Object value = null;
        try {
            key = kv.getKey();
            value = kv.getValue();
        } catch (Throwable t) {
            // ignore if getters not available
            continue;
        }
        if (key == null) {
            continue;
        }
        if (value == null) {
            json.add(key, JsonNull.INSTANCE);
        } else if (value instanceof Number) {
            json.addProperty(key, ((Number) value).doubleValue());
        } else if (value instanceof Boolean) {
            json.addProperty(key, (Boolean) value);
        } else {
            json.addProperty(key, value.toString());
        }
    }
    return json;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removed = 0;
    java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(root);
    java.util.function.Function<Category, Integer> countFunc = new java.util.function.Function<Category, Integer>() {
        public Integer apply(Category n) {
            int c = 1;
            for (Category child : n.getChildren()) {
                c += this.apply(child);
            }
            return c;
        }
    };
    try {
        while (!stack.isEmpty()) {
            Category curr = stack.pop();
            java.util.List<Category> children = new java.util.ArrayList<>(curr.getChildren());
            for (Category child : children) {
                if (!child.isActive()) {
                    curr.getChildren().remove(child);
                    removed += countFunc.apply(child);
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        // Exception handling can be extended as needed
    }
    return removed;
}

