final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (constantPoolEntryIndex < 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be non‑negative");
    }
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer must not be null");
    }
    // In typical class file parsing we keep a reference to the raw class file bytes.
    // This field is assumed to be available in the containing class.
    try {
        // The index supplied is expected to be the absolute offset of the
        // CONSTANT_Utf8 tag in the class file byte array.
        if (classFileBuffer == null || constantPoolEntryIndex >= classFileBuffer.length) {
            throw new IndexOutOfBoundsException("invalid constant pool entry index");
        }

        // The tag byte must be 0x01 for CONSTANT_Utf8
        if ((classFileBuffer[constantPoolEntryIndex] & 0xFF) != 0x01) {
            throw new IllegalStateException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
        }

        // Read the two‑byte length of the UTF‑8 string
        final int lenIndex = constantPoolEntryIndex + 1;
        int utfLength = ((classFileBuffer[lenIndex] & 0xFF) << 8) |
                        (classFileBuffer[lenIndex + 1] & 0xFF);

        final int stringStart = constantPoolEntryIndex + 3;
        if (stringStart + utfLength > classFileBuffer.length) {
            throw new IndexOutOfBoundsException("UTF‑8 string extends beyond class file buffer");
        }

        // Ensure the external buffer is large enough (if the caller intends to reuse it)
        if (charBuffer.length < utfLength) {
            throw new IllegalArgumentException("charBuffer too small to hold UTF‑8 string");
        }

        // Convert the byte sequence to a String using UTF‑8 encoding.
        // This constructor creates a String directly from a byte array
        // without intermediate character array allocation.
        return new String(classFileBuffer, stringStart, utfLength, java.nio.charset.StandardCharsets.UTF_8);
    } catch (RuntimeException e) {
        // Propagate runtime issues unchanged
        throw e;
    } catch (Exception e) {
        // Wrap any unexpected checked exception
        throw new RuntimeException(e);
    }
}

