private String parseToken(final char[] terminators){
    // Guard against null or empty terminator list – return the rest of the buffer
    if (terminators == null || terminators.length == 0){
        if (pos > len) pos = len;
        return new String(chars, pos, Math.max(0, len - pos));
    }
    // Start of token
    int start = pos;
    // Scan until a terminator or end of buffer
    while (pos < len){
        char current = chars[pos];
        boolean isTerminator = false;
        for (char t : terminators){
            if (current == t){
                isTerminator = true;
                break;
            }
        }
        if (isTerminator){
            break;   // Token ends before the terminator
        }
        pos++;
    }
    // Return the token and leave pos at the terminator (or end of buffer)
    int length = Math.max(0, pos - start);
    return new String(chars, start, length);
}

