private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSums = new ArrayList<>();
    long total = 0L;
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(suffixSums, total);
    }
    try {
        for (Integer val : bounds) {
            int v = (val == null) ? 0 : val;
            total += v;
        }
        long suffix = 0L;
        for (int i = bounds.size() - 1; i >= 0; i--) {
            Integer val = bounds.get(i);
            int v = (val == null) ? 0 : val;
            suffix += v;
            // Casting to int for the suffix list; if overflow occurs it will wrap around
            suffixSums.add(0, (int) suffix);
        }
    } catch (Exception e) {
        // In case of any runtime errors, return whatever has been computed so far
        return new Pair<>(suffixSums, total);
    }
    return new Pair<>(suffixSums, total);
}

