private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null){
        throw new IllegalArgumentException("list cannot be null");
    }
    if (list.size == 0){
        return;
    }
    ListNode<E> thisTail = this.tail;
    ListNode<E> otherHead = list.head;
    ListNode<E> otherTail = list.tail;
    if (thisTail != null){
        thisTail.next = otherHead;
        if (otherHead != null){
            otherHead.prev = thisTail;
        }
    } else {
        this.head = otherHead;
    }
    this.tail = otherTail;
    this.size += list.size;
    list.head = null;
    list.tail = null;
    list.size = 0;
}

