public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }
    try {
        // Execute on Event Dispatch Thread
        javax.swing.SwingUtilities.invokeLater(() -> {
            // Select the desired row
            table.setRowSelectionInterval(row, row);
            table.setColumnSelectionInterval(0, 0);
            // Scroll to the selected row
            int column = table.getSelectedColumn();
            if (column < 0) {
                column = 0;
            }
            java.awt.Rectangle cellRect = table.getCellRect(row, column, true);
            table.scrollRectToVisible(cellRect);
            // Repaint after a short delay to ensure proper drawing
            new javax.swing.Timer(50, e -> table.repaint()).start();
        });
    } catch (Exception e) {
        // Safely ignore any exceptions to avoid breaking the caller
    }
}

