}

private List<Integer> computeLowerBounds(List<K> keys){
    // Handle null input
    if (keys == null) {
        return java.util.Collections.emptyList();
    }
    // Prepare result list with same capacity as input list
    List<Integer> lowerBounds = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        Integer bound = null;
        try {
            if (key == null) {
                // Preserve null position for missing key
                bound = null;
            } else if (key instanceof java.lang.Number) {
                // If key is a numeric type, use its integer value
                bound = ((java.lang.Number) key).intValue();
            } else {
                // Default fallback for non‑numeric keys
                bound = 0;
            }
        } catch (Exception e) {
            // In case of any unexpected runtime issue, record a sentinel value
            bound = null;
        }
        lowerBounds.add(bound);
    }
    return lowerBounds;
}

private void pop(final String descriptor){
    if (descriptor == null) {
        throw new NullPointerException("descriptor");
    }
    int length = descriptor.length();
    int index = 0;
    // method descriptor
    if (descriptor.charAt(0) == '(') {
        index = 1;
        while (index < length && descriptor.charAt(index) != ')') {
            char c = descriptor.charAt(index);
            if (c == 'L') {
                int semicolon = descriptor.indexOf(';', index);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';'");
                }
                stack.pop();
                index = semicolon + 1;
            } else if (c == '[') {
                // array type – pop a single reference slot
                while (index < length && descriptor.charAt(index) == '[') {
                    index++;
                }
                // after brackets, pop one slot for the array reference
                stack.pop();
            } else { // primitive
                int count = (c == 'J' || c == 'D') ? 2 : 1;
                for (int n = 0; n < count; n++) {
                    stack.pop();
                }
                index++;
            }
        }
        // skip ')', return type is not popped
    } else {
        // single type descriptor
        char c = descriptor.charAt(index);
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', index);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid descriptor: missing ';'");
            }
            stack.pop();
        } else if (c == '[') {
            while (index < length && descriptor.charAt(index) == '[') {
                index++;
            }
            // pop one slot for the array reference
            stack.pop();
        } else { // primitive
            int count = (c == 'J' || c == 'D') ? 2 : 1;
            for (int n = 0; n < count; n++) {
                stack.pop();
            }
        }
    }
}

