public static String applyRelativePath(String path,String relativePath){
    try{
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path rel  = java.nio.file.Paths.get(relativePath);
        java.nio.file.Path resolved = base.resolve(rel).normalize();
        String result = resolved.toString().replace(java.io.File.separatorChar,'/');
        return result;
    }catch(Throwable t){
        // fallback: simple string concatenation if path resolution fails
        String separator = java.io.File.separator;
        String combined = path;
        if(!combined.endsWith(separator)) combined += separator;
        combined += relativePath;
        return combined.replace(java.io.File.separatorChar,'/');
    }
}

