static String[] toNoNullStringArray(Object[] array){ 
    if (array == null) { 
        return new String[0]; 
    } 
    int nullCount = 0; 
    for (Object obj : array) { 
        if (obj == null) { 
            nullCount++; 
        } 
    } 
    if (nullCount == 0) { 
        // If array is already a String[] return it directly
        if (array instanceof String[]) { 
            return (String[]) array; 
        } 
        // Otherwise copy into a new String array
        String[] result = new String[array.length]; 
        for (int i = 0; i < array.length; i++) { 
            result[i] = (String) array[i]; 
        } 
        return result; 
    } 
    // Filter out null elements
    String[] temp = new String[array.length - nullCount]; 
    int idx = 0; 
    for (Object obj : array) { 
        if (obj != null) { 
            temp[idx++] = (String) obj; 
        } 
    } 
    String[] result = new String[idx]; 
    System.arraycopy(temp, 0, result, 0, idx); 
    return result; 
}

