    // If the current field isn't length-delimited, it's not a packed field.
    if (this.currentWireType != WIRETYPE_LENGTH_DELIMITED) {
        return;
    }
    // Retrieve the descriptor for the current field.
    FieldDescriptor descriptor = this.getDescriptorForField(this.currentFieldNumber);
    if (descriptor == null) {
        return;
    }
    // Check if the field is a repeated packable field and we aren't already in packed mode.
    if (descriptor.isRepeated() && descriptor.isPackable() && !this.packedFieldActive) {
        this.packedFieldActive = true;
    }
}

