public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("File must not be null");
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Attempt to parse a snapshot from the line. If parsing fails, skip the line.
            ThreadSnapshot snapshot;
            try {
                snapshot = ThreadSnapshot.parse(line);
            } catch (Exception e) {
                // Log the error or continue silently
                continue;
            }
            if (snapshot == null) {
                continue;
            }
            // If no time ranges are supplied, accept all snapshots.
            if (timeRanges == null || timeRanges.isEmpty()) {
                result.add(snapshot);
                continue;
            }
            long tsTime = snapshot.getTimestamp(); // Assumed method
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStartTime(); // Assumed method
                long end = range.getEndTime();     // Assumed method
                if (tsTime >= start && tsTime <= end) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}
